INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1111051500', 0, 'Cheongunhyoja-dong', '청운효자동', 'Jongno-gu', '종로구', 'M599.43,389.81 L605.25,400.32 L606.56,400.83 L607.75,401.73 L614.6,409.39 L615.85,414 L618.28,431.7 L616.64,438.37 L616.15,449.72 L608.4,450.86 L601.07,450.46 L599.68,437.41 L592.61,436.86 L588.46,437.6 L587.79,438.28 L587.76,440.37 L587.04,441.84 L586.46,442.51 L585.72,442.5 L583.18,441.37 L581.45,438.74 L581.37,436.48 L568.15,436.96 L562.06,432.06 L554.16,421.17 L553.93,416.93 L556.98,413.46 L557.89,412.95 L558.71,413.27 L559.32,413.16 L565.15,410.91 L566.65,409.82 L569.36,406.67 L572.43,402.1 L572.09,399.06 L573.44,395.5 L578.8,388.48 L583.7,386.06 L585.94,386.97 L593.46,385.79 L594.58,385.14 L599.3,387.31 L599.43,389.81 Z', 'held', '["government"]', 'Cheongunhyoja-dong, Jongno-gu. No inhabited station stands in this dong. Its buildings are buried in snow, and the dong chief of Sajik-dong, where the nearest station, Gyeongbokgung, belongs, also holds its surface land, scavenging, light-field plots and exit rights. Above, the Member of the National Assembly for Jongno-gu (Claw Party) holds the duchy.', '종로구 청운효자동. 사람이 사는 역이 없는 동이다. 지상의 건물은 눈에 묻혔고, 가장 가까운 경복궁역이 속한 사직동의 동장이 이 동의 지상 땅과 고물 채집, 빛밭 자리, 출입구 권리를 함께 쥔다. 위로는 종로구 국회의원(클로당)이 이 공작령을 쥔다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Cheongunhyoja-dong, and only by day. The long-night ration grades have been posted. Ahead of the third water contract the dong chief recounts the station quota and its water allotment.', '2126년 겨울. 청운효자동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 긴 밤 철 배급 등급이 고시됐다. 동장은 세 번째 급수계약을 앞두고 역의 정원과 물 배정을 다시 센다.', 0, 2436487.2405403084, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1111053000', 1, 'Sajik-dong', '사직동', 'Jongno-gu', '종로구', 'M608.68,474.1 L605.65,473.57 L600.94,473.81 L585.79,477.57 L577.89,472.1 L576.32,470.35 L576.89,469.87 L577.15,465.45 L570.49,452.36 L568.88,447.63 L568.18,446.99 L568.15,436.96 L581.37,436.48 L581.45,438.74 L583.18,441.37 L585.72,442.5 L586.46,442.51 L587.04,441.84 L587.76,440.37 L587.79,438.28 L588.46,437.6 L592.61,436.86 L599.68,437.41 L601.07,450.46 L608.4,450.86 L608.68,474.1 Z', 'held', '["government"]', 'Sajik-dong, Jongno-gu. About 1,000 registered people live at the two stations Gyeongbokgung and Gwanghwamun. The dong chief of Sajik-dong keeps the ration ledger and the death strikes at the community service centre in Gyeongbokgung Station; above the dong, the Member of the National Assembly for Jongno-gu (Claw Party) holds the duchy. Gwanghwamun Station is joined by tunnel to the Government Complex Seoul; the Assembly sits in the old meeting room under the main building.', '종로구 사직동. 경복궁·광화문 두 역에 약 1,000명이 기재되어 산다. 사직동 동장이 경복궁역의 동주민센터에서 배급 장부와 사망 말소를 맡고, 위로는 종로구 국회의원(클로당)이 이 공작령을 쥔다. 광화문역은 정부서울청사와 터널로 이어진다. 국회는 청사 본관 지하의 옛 회의실에서 열린다.', 'Winter 2126. In the Government Complex the two parties are split over the wording of the third water contract annex.', '2126년 겨울. 청사에서는 세 번째 급수계약 부속서의 문안을 두고 두 당이 갈린다.', 2, 1164909.8759920564, 858);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1111054000', 2, 'Samcheong-dong', '삼청동', 'Jongno-gu', '종로구', 'M625.4,381.06 L629.9,386.43 L634.14,389.29 L636.2,390.33 L639.19,391.28 L642.72,391.82 L644.77,392.94 L643.61,394.38 L640.22,397.37 L635.36,402.89 L634.6,408.64 L632.8,413.21 L631.75,415.05 L628.13,417.42 L625.82,422.85 L625.65,425.91 L628.92,440.95 L630.63,444.89 L633.18,447.31 L626.32,451.4 L616.15,449.72 L616.64,438.37 L618.28,431.7 L615.85,414 L614.6,409.39 L607.75,401.73 L606.56,400.83 L605.25,400.32 L599.43,389.81 L599.3,387.31 L605.84,375.56 L620.72,381.04 L625.4,381.06 Z', 'held', '["government"]', 'Samcheong-dong, Jongno-gu. No inhabited station stands in this dong. Its buildings are buried in snow, and the dong chief of Jongno 1·2·3·4-ga-dong, where the nearest station, Anguk, belongs, also holds its surface land, scavenging, light-field plots and exit rights. Above, the Member of the National Assembly for Jongno-gu (Claw Party) holds the duchy.', '종로구 삼청동. 사람이 사는 역이 없는 동이다. 지상의 건물은 눈에 묻혔고, 가장 가까운 안국역이 속한 종로1·2·3·4가동의 동장이 이 동의 지상 땅과 고물 채집, 빛밭 자리, 출입구 권리를 함께 쥔다. 위로는 종로구 국회의원(클로당)이 이 공작령을 쥔다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Samcheong-dong, and only by day. The long-night ration grades have been posted. Ahead of the third water contract the dong chief recounts the station quota and its water allotment.', '2126년 겨울. 삼청동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 긴 밤 철 배급 등급이 고시됐다. 동장은 세 번째 급수계약을 앞두고 역의 정원과 물 배정을 다시 센다.', 0, 1360426.2034549685, 0);
