INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1126066000', 108, 'Mangu 3-dong', '망우3동', 'Jungnang-gu', '중랑구', 'M990.27,410.36 L989.24,409.35 L984.64,407.27 L982.01,408.05 L978.8,408.22 L975.33,407.85 L953.79,398.85 L943,401.77 L941.84,385.93 L961.6,380.63 L963.82,383.98 L970.09,383.17 L979.76,383.93 L984.47,384.66 L996.79,394.38 L990.27,410.36 Z', 'held', '["government"]', 'Mangu 3-dong, Jungnang-gu. No inhabited station stands in this dong. Its buildings are buried in snow, and the dong chief of Sangbong 1-dong, where the nearest station, Mangu, belongs, also holds its surface land, scavenging, light-field plots and exit rights. Above, the Member of the National Assembly for Jungnang-gu (Claw Party) holds the duchy.', '중랑구 망우3동. 사람이 사는 역이 없는 동이다. 지상의 건물은 눈에 묻혔고, 가장 가까운 망우역이 속한 상봉1동의 동장이 이 동의 지상 땅과 고물 채집, 빛밭 자리, 출입구 권리를 함께 쥔다. 위로는 중랑구 국회의원(클로당)이 이 공작령을 쥔다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Mangu 3-dong, and only by day. The long-night ration grades have been posted. Ahead of the third water contract the dong chief recounts the station quota and its water allotment.', '2126년 겨울. 망우3동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 긴 밤 철 배급 등급이 고시됐다. 동장은 세 번째 급수계약을 앞두고 역의 정원과 물 배정을 다시 센다.', 0, 990447.9873087407, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1126068000', 109, 'Sinnae 1-dong', '신내1동', 'Jungnang-gu', '중랑구', 'M1010.25,302.4 L1009.38,308.38 L1011.94,323.01 L1009.65,329.48 L1009.12,333.38 L999.11,330.98 L996.6,328.4 L988.5,321.62 L976.14,318.02 L972.15,317.18 L965.46,317.43 L964.7,331.48 L967.52,332.37 L970.08,330.21 L970.94,329.93 L971.82,330.62 L972.42,333.35 L972.27,336.07 L970.63,343.63 L962.75,362.98 L948.57,366.82 L949.4,362.68 L951.73,361.38 L948.34,348.13 L947.62,337.68 L948.03,334.88 L950.14,329.49 L951.28,321.71 L951.36,318.86 L949.84,310.59 L934.46,301.86 L931.78,294.1 L941.78,299.91 L950.64,303.33 L953.2,303.53 L963.13,296.98 L966.03,293.67 L978.08,290.01 L979.3,290.87 L986.78,291.39 L990.68,290.32 L992.79,290.28 L994.58,290.9 L998.18,292.85 L1001.63,295.17 L1006.58,295.67 L1010.25,302.4 Z', 'held', '["government"]', 'Sinnae 1-dong, Jungnang-gu. No inhabited station stands in this dong. Its buildings are buried in snow, and the dong chief of Mangubon-dong, where the nearest station, Sinnae, belongs, also holds its surface land, scavenging, light-field plots and exit rights. Above, the Member of the National Assembly for Jungnang-gu (Claw Party) holds the duchy.', '중랑구 신내1동. 사람이 사는 역이 없는 동이다. 지상의 건물은 눈에 묻혔고, 가장 가까운 신내역이 속한 망우본동의 동장이 이 동의 지상 땅과 고물 채집, 빛밭 자리, 출입구 권리를 함께 쥔다. 위로는 중랑구 국회의원(클로당)이 이 공작령을 쥔다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Sinnae 1-dong, and only by day. The long-night ration grades have been posted. Ahead of the third water contract the dong chief recounts the station quota and its water allotment.', '2126년 겨울. 신내1동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 긴 밤 철 배급 등급이 고시됐다. 동장은 세 번째 급수계약을 앞두고 역의 정원과 물 배정을 다시 센다.', 1, 2488480.096156416, 0);
