INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1144055500', 207, 'Ahyeon-dong', '아현동', 'Mapo-gu', '마포구', 'M553.2,524.41 L542.23,549.74 L537.08,558.68 L536.64,558.46 L532.03,566.01 L532.54,566.44 L524.65,562 L524.35,559.38 L526.41,557.29 L530.72,551.3 L532.76,532.05 L532.08,528.45 L529.87,524.67 L527.4,523.19 L527.68,517.64 L543.35,516.54 L545.27,516.07 L551.25,515.95 L555.3,516.84 L555.93,518.92 L553.2,524.41 Z', 'held', '["government"]', 'Ahyeon-dong, Mapo-gu. About 500 registered people live at Aeogae Station. The dong chief of Ahyeon-dong keeps the ration ledger and the death strikes at the community service centre in Aeogae Station; above the dong, the Member of the National Assembly for Mapo-gu (OMO Party) holds the duchy.', '마포구 아현동. 애오개역에 약 500명이 기재되어 산다. 아현동 동장이 애오개역의 동주민센터에서 배급 장부와 사망 말소를 맡고, 위로는 마포구 국회의원(OMO당)이 이 공작령을 쥔다.', 'Winter 2126. The annex of the third water contract waits on this district''s Assembly Member''s stamp. Guards at the bridge ends and checkpoints have been doubled, and the community service centres field complaints asking whether water quotas will change after the contract.', '2126년 겨울. 세 번째 급수계약의 부속서가 이 구 국회의원의 도장에 걸려 있다. 다리 끝과 검문소의 경비가 늘었고, 동주민센터는 계약 뒤 물 배정이 바뀌는지 묻는 민원을 받는다.', 2, 730708.7363626242, 684);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1144056500', 208, 'Gongdeok-dong', '공덕동', 'Mapo-gu', '마포구', 'M570.78,543.69 L570.03,546.92 L568.63,547.73 L567.87,547.36 L564.09,551.23 L555.47,558.8 L553.05,568.44 L552.74,571.38 L548.98,576.75 L532.03,566.01 L536.64,558.46 L537.08,558.68 L542.23,549.74 L553.2,524.41 L555.93,518.92 L563.92,511.07 L568.36,513.51 L568.85,517.23 L568.5,519.85 L565.47,523.78 L564.87,523.48 L564.48,523.71 L564.44,532.27 L566.36,537.54 L570.78,543.69 Z', 'held', '["government"]', 'Gongdeok-dong, Mapo-gu. About 3,500 registered people live at Gongdeok Station. The dong chief of Gongdeok-dong keeps the ration ledger and the death strikes at the community service centre in Gongdeok Station; above the dong, the Member of the National Assembly for Mapo-gu (OMO Party) holds the duchy. The Gongdeok market is held at the district''s seat station; goods from across the river come in here. Mapo-gu holds Mapo–Yeouinaru, the only under-river tunnel between the Government and the Free Cities, the north ends of the Hapjeong–Dangsan and Digital Media City–Magongnaru bridges, and the Gongdeok market.', '마포구 공덕동. 공덕역에 약 3,500명이 기재되어 산다. 공덕동 동장이 공덕역의 동주민센터에서 배급 장부와 사망 말소를 맡고, 위로는 마포구 국회의원(OMO당)이 이 공작령을 쥔다. 공덕 장터가 이 구의 본역에 선다. 강 건너 물자가 이곳으로 들어온다. 마포구는 정부와 자유도시들 사이의 유일한 강 밑 터널인 마포–여의나루와, 합정–당산·디지털미디어시티–마곡나루 다리의 북쪽 끝, 공덕 장터를 쥔다.', 'Winter 2126. The annex of the third water contract waits on this district''s Assembly Member''s stamp. Guards at the bridge ends and checkpoints have been doubled, and the community service centres field complaints asking whether water quotas will change after the contract.', '2126년 겨울. 세 번째 급수계약의 부속서가 이 구 국회의원의 도장에 걸려 있다. 다리 끝과 검문소의 경비가 늘었고, 동주민센터는 계약 뒤 물 배정이 바뀌는지 묻는 민원을 받는다.', 1, 1018043.9931745825, 3438);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1144058500', 209, 'Dohwa-dong', '도화동', 'Mapo-gu', '마포구', 'M548.98,576.75 L539.2,586.55 L539.08,588.06 L538.67,588.57 L536.96,590.29 L533.77,592.4 L524.26,594.47 L520.21,594.01 L519.22,594.54 L516.42,596.9 L515.22,601.15 L505.37,591.37 L512.67,585.91 L528.27,572.1 L532.69,566.53 L548.98,576.75 Z', 'held', '["government"]', 'Dohwa-dong, Mapo-gu. No inhabited station stands in this dong. Its buildings are buried in snow, and the dong chief of Yonggang-dong, where the nearest station, Mapo, belongs, also holds its surface land, scavenging, light-field plots and exit rights. Above, the Member of the National Assembly for Mapo-gu (OMO Party) holds the duchy.', '마포구 도화동. 사람이 사는 역이 없는 동이다. 지상의 건물은 눈에 묻혔고, 가장 가까운 마포역이 속한 용강동의 동장이 이 동의 지상 땅과 고물 채집, 빛밭 자리, 출입구 권리를 함께 쥔다. 위로는 마포구 국회의원(OMO당)이 이 공작령을 쥔다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Dohwa-dong, and only by day. The annex of the third water contract waits on this district''s Assembly Member''s stamp. Guards at the bridge ends and checkpoints have been doubled, and the community service centres field complaints asking whether water quotas will change after the contract.', '2126년 겨울. 도화동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약의 부속서가 이 구 국회의원의 도장에 걸려 있다. 다리 끝과 검문소의 경비가 늘었고, 동주민센터는 계약 뒤 물 배정이 바뀌는지 묻는 민원을 받는다.', 0, 604231.7845057779, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1144059000', 210, 'Yonggang-dong', '용강동', 'Mapo-gu', '마포구', 'M515.05,560.12 L517.88,562.49 L524.41,566.61 L528.5,566.82 L529.79,564.99 L532.69,566.53 L528.27,572.1 L512.67,585.91 L505.37,591.37 L489.95,582.12 L492.35,573.49 L493.59,570.75 L504.2,554.78 L515.05,560.12 Z', 'held', '["government"]', 'Yonggang-dong, Mapo-gu. About 500 registered people live at Mapo Station. The dong chief of Yonggang-dong keeps the ration ledger and the death strikes at the community service centre in Mapo Station; above the dong, the Member of the National Assembly for Mapo-gu (OMO Party) holds the duchy. Mapo Station is the north mouth of the Line 5 under-river tunnel to Yeouinaru; the Government''s ledger checkpoint stands at the mouth.', '마포구 용강동. 마포역에 약 500명이 기재되어 산다. 용강동 동장이 마포역의 동주민센터에서 배급 장부와 사망 말소를 맡고, 위로는 마포구 국회의원(OMO당)이 이 공작령을 쥔다. 마포역은 여의나루로 가는 5호선 강 밑 터널의 북쪽 입구다. 입구에 정부의 장부 검문소가 있다.', 'Winter 2126. Until the contract the Mapo tunnel checkpoint checks every load against the ledger twice.', '2126년 겨울. 마포 터널 검문소는 계약 전까지 짐마다 장부 대조를 두 번 한다.', 1, 775405.8526518587, 645);
