INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1144063000', 213, 'Sinsu-dong', '신수동', 'Mapo-gu', '마포구', 'M504.2,554.78 L493.59,570.75 L492.35,573.49 L489.95,582.12 L474.09,573.66 L467.62,572.98 L474.47,559.9 L477.38,560.12 L478.88,558.78 L480.86,552.05 L482.01,542.51 L482.04,537.12 L484.25,531.28 L485.21,533.09 L488.94,536.09 L492.16,537.58 L494.92,540.2 L501.86,551.12 L501.74,551.99 L504.2,554.78 Z', 'held', '["government"]', 'Sinsu-dong, Mapo-gu. No inhabited station stands in this dong. Its buildings are buried in snow, and the dong chief of Seogang-dong, where the nearest station, Gwangheungchang, belongs, also holds its surface land, scavenging, light-field plots and exit rights. Above, the Member of the National Assembly for Mapo-gu (OMO Party) holds the duchy.', '마포구 신수동. 사람이 사는 역이 없는 동이다. 지상의 건물은 눈에 묻혔고, 가장 가까운 광흥창역이 속한 서강동의 동장이 이 동의 지상 땅과 고물 채집, 빛밭 자리, 출입구 권리를 함께 쥔다. 위로는 마포구 국회의원(OMO당)이 이 공작령을 쥔다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Sinsu-dong, and only by day. The annex of the third water contract waits on this district''s Assembly Member''s stamp. Guards at the bridge ends and checkpoints have been doubled, and the community service centres field complaints asking whether water quotas will change after the contract.', '2126년 겨울. 신수동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약의 부속서가 이 구 국회의원의 도장에 걸려 있다. 다리 끝과 검문소의 경비가 늘었고, 동주민센터는 계약 뒤 물 배정이 바뀌는지 묻는 민원을 받는다.', 0, 819820.8483280803, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1144065500', 214, 'Seogang-dong', '서강동', 'Mapo-gu', '마포구', 'M484.25,531.28 L482.04,537.12 L482.01,542.51 L480.86,552.05 L478.88,558.78 L477.38,560.12 L474.47,559.9 L467.62,572.98 L474.09,573.66 L466.5,581.86 L453.34,576.14 L451.68,573.28 L436.38,573.06 L436.35,568.17 L435.26,565.71 L443.92,551.92 L445.68,548.31 L450.16,545.51 L457.03,538.96 L456.66,534.29 L459.39,530.89 L471.64,527.45 L476.34,525.46 L485.29,530.15 L484.25,531.28 Z', 'held', '["government"]', 'Seogang-dong, Mapo-gu. About 1,000 registered people live at the two stations Gwangheungchang and Sangsu. The dong chief of Seogang-dong keeps the ration ledger and the death strikes at the community service centre in Gwangheungchang Station; above the dong, the Member of the National Assembly for Mapo-gu (OMO Party) holds the duchy.', '마포구 서강동. 광흥창·상수 두 역에 약 1,000명이 기재되어 산다. 서강동 동장이 광흥창역의 동주민센터에서 배급 장부와 사망 말소를 맡고, 위로는 마포구 국회의원(OMO당)이 이 공작령을 쥔다.', 'Winter 2126. The annex of the third water contract waits on this district''s Assembly Member''s stamp. Guards at the bridge ends and checkpoints have been doubled, and the community service centres field complaints asking whether water quotas will change after the contract.', '2126년 겨울. 세 번째 급수계약의 부속서가 이 구 국회의원의 도장에 걸려 있다. 다리 끝과 검문소의 경비가 늘었고, 동주민센터는 계약 뒤 물 배정이 바뀌는지 묻는 민원을 받는다.', 2, 1484524.7425528131, 674);
