INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1144074000', 222, 'Sangam-dong', '상암동', 'Mapo-gu', '마포구', 'M383.06,440.11 L392.85,448.6 L396.27,444.2 L397.14,445.13 L392.76,450.25 L388.96,456.07 L385.53,458.16 L373.14,460.18 L372.06,459.98 L370.71,458.03 L369.59,458.03 L366.06,459.16 L365.33,459.96 L362.89,466.49 L362.7,470.78 L364.99,475.54 L367.35,478.28 L373.21,482.42 L373.88,487.06 L371.78,494.88 L369.62,500.68 L371.52,506.17 L367.51,509.43 L371.72,514.62 L364.13,529.36 L360.74,537.48 L331.5,519.28 L307.66,505.21 L282.1,487.17 L271.95,478.74 L259.62,469.12 L255.03,462.5 L256.68,455.13 L271.04,451.59 L278.52,448.08 L287.77,448.21 L292.63,446.02 L296.51,442.67 L311.88,437.54 L320.23,437.17 L322.57,437.4 L324.18,434.37 L323.73,432.35 L321.37,427.83 L321.54,418.61 L324.34,411.14 L332.02,398.81 L337.65,394.18 L359.49,417.71 L365.92,423.16 L374.81,428.53 L377.48,430.74 L382.24,436.83 L383.06,440.11 Z', 'held', '["government"]', 'Sangam-dong, Mapo-gu. About 3,500 registered people live at Digital Media City Station. The dong chief of Sangam-dong keeps the ration ledger and the death strikes at the community service centre in Digital Media City Station; above the dong, the Member of the National Assembly for Mapo-gu (OMO Party) holds the duchy. Digital Media City is the north end of the Airport Railroad bridge to Magongnaru.', '마포구 상암동. 디지털미디어시티역에 약 3,500명이 기재되어 산다. 상암동 동장이 디지털미디어시티역의 동주민센터에서 배급 장부와 사망 말소를 맡고, 위로는 마포구 국회의원(OMO당)이 이 공작령을 쥔다. 디지털미디어시티는 마곡나루로 건너는 공항철도 다리의 북쪽 끝이다.', 'Winter 2126. The annex of the third water contract waits on this district''s Assembly Member''s stamp. Guards at the bridge ends and checkpoints have been doubled, and the community service centres field complaints asking whether water quotas will change after the contract.', '2126년 겨울. 세 번째 급수계약의 부속서가 이 구 국회의원의 도장에 걸려 있다. 다리 끝과 검문소의 경비가 늘었고, 동주민센터는 계약 뒤 물 배정이 바뀌는지 묻는 민원을 받는다.', 2, 8598210.297691036, 407);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1147051000', 223, 'Mok 1-dong', '목1동', 'Yangcheon-gu', '양천구', 'M354.11,611.06 L349.69,618.46 L347.84,620.61 L345.05,622.18 L334.66,626.77 L331.13,630.69 L329.09,641.59 L313.71,639.79 L304.28,638.06 L296.94,635.01 L287.75,639.97 L284.74,626.83 L283.95,613.91 L315.62,608.86 L334.07,606.7 L340.53,607.16 L344.34,607.98 L348.23,608.88 L354.11,611.06 Z', 'held', '["free-city"]', 'Mok 1-dong, Yangcheon-gu. It lies in the Mok-dong section of Yangcheon; about 1,800 people live at the three stations Mok-dong, Yangpyeong and Omokgyo. Each station''s foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Yangcheon Depot Master.', '양천구 목1동. 양천의 목동 구간에 든 동으로, 목동·양평·오목교 세 역에 약 1,800명이 산다. 역마다 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 양천 기지장이다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 2, 1563520.8978151572, 1151);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1147052000', 224, 'Mok 2-dong', '목2동', 'Yangcheon-gu', '양천구', 'M340.12,563.11 L335.51,564.65 L322.87,572.06 L313.87,580.49 L308.95,586.1 L296.97,578.03 L295.44,576.35 L290.47,562.44 L290.96,560.34 L292.49,557.19 L297.34,551.27 L301.67,552.14 L303.56,549.78 L308.47,551.76 L313.04,552.45 L315.9,552.36 L324.85,551.49 L332.25,549.18 L339.46,557.56 L344.88,564.67 L340.12,563.11 Z', 'held', '["free-city"]', 'Mok 2-dong, Yangcheon-gu. It lies in the Mok-dong section of Yangcheon; about 600 people live at Sinmokdong Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Yangcheon Depot Master.', '양천구 목2동. 양천의 목동 구간에 든 동으로, 신목동역에 약 600명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 양천 기지장이다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 1053479.979277882, 570);
