INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150060300', 252, 'Gayang 1-dong', '가양1동', 'Gangseo-gu', '강서구', 'M243.44,465.45 L239.44,471.5 L243.86,475.03 L247.15,478.65 L241.3,489.05 L232.98,487.8 L218.81,478.98 L210.75,509.85 L178.54,505.54 L181.11,480.62 L167.82,479.11 L166.29,473.68 L166.75,469.71 L166.61,465.94 L165.51,457.28 L161.95,453.93 L161.42,449.34 L162.7,442.64 L168.34,435.65 L171.12,433.39 L173.15,432.64 L176.16,427.38 L184.5,417.98 L193.9,411.81 L249.54,457.23 L243.44,465.45 Z', 'held', '["free-city"]', 'Gayang 1-dong, Gangseo-gu. It lies in the Magok section of Gangseo; about 2,850 people live at the two stations Magongnaru and Yangcheon Hyanggyo. Each station''s foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Gangseo Wind Keeper. Magongnaru is the south end of the Airport Railroad bridge to Digital Media City.', '강서구 가양1동. 강서의 마곡 구간에 든 동으로, 마곡나루·양천향교 두 역에 약 2,850명이 산다. 역마다 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 강서 바람지기다. 마곡나루는 디지털미디어시티로 건너는 공항철도 다리의 남쪽 끝이다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 2, 4882081.775596216, 584);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150060400', 253, 'Gayang 2-dong', '가양2동', 'Gangseo-gu', '강서구', 'M259.62,469.12 L271.95,478.74 L265.64,488.48 L259.4,501.19 L241.3,489.05 L247.15,478.65 L243.86,475.03 L239.44,471.5 L243.44,465.45 L249.54,457.23 L255.03,462.5 L259.62,469.12 Z', 'held', '["free-city"]', 'Gayang 2-dong, Gangseo-gu. It lies in the Gayang section of Gangseo; about 600 people live at Gayang Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Gangseo Wind Keeper.', '강서구 가양2동. 강서의 가양 구간에 든 동으로, 가양역에 약 600명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 강서 바람지기다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 699428.42181557, 858);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150060500', 254, 'Gayang 3-dong', '가양3동', 'Gangseo-gu', '강서구', 'M279.01,493.11 L295.31,504.08 L294.34,506.05 L289.21,508.49 L281.82,516.41 L259.4,501.19 L265.64,488.48 L271.95,478.74 L282.1,487.17 L279.01,493.11 Z', 'held', '["free-city"]', 'Gayang 3-dong, Gangseo-gu. No inhabited station stands in this dong. The ground is buried in snow, and the chief of the Gayang section, which holds the nearest station, Jeungmi, also holds its scavenging and light-field plots. The city is held by the Gangseo Wind Keeper.', '강서구 가양3동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 증미역이 든 가양 구간의 구간장이 이 동의 고물 채집과 빛밭 자리를 함께 쥔다. 이 도시를 쥔 사람은 강서 바람지기다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Gayang 3-dong, and only by day. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 가양3동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 0, 601207.7955141984, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150061100', 255, 'Balsan 1-dong', '발산1동', 'Gangseo-gu', '강서구', 'M210.75,509.85 L205.23,531.3 L204.98,547.94 L196.48,547.88 L195.67,549.9 L189.89,549.65 L189.08,548.21 L186.19,548.91 L180.06,548.81 L179.88,551.06 L177.7,555.64 L175.2,559.5 L174.6,562.23 L175.72,566.32 L173.19,568.68 L173.61,570.48 L164.24,573.91 L156.43,573.49 L148.39,574.2 L136.2,573.6 L138.95,569.79 L139.09,564.37 L142.19,563.1 L144.59,559.78 L144.94,555.98 L139.59,549.42 L141.84,546.46 L137.4,541.53 L147.23,532.44 L149.92,529.53 L152.07,528.24 L167.55,513.71 L168.31,511.54 L168.88,506.81 L168.52,504.17 L210.75,509.85 Z', 'held', '["free-city"]', 'Balsan 1-dong, Gangseo-gu. It lies in the Magok section of Gangseo; about 600 people live at Balsan Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Gangseo Wind Keeper.', '강서구 발산1동. 강서의 마곡 구간에 든 동으로, 발산역에 약 600명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 강서 바람지기다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 2956901.379433693, 203);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150061500', 256, 'Ujangsan-dong', '우장산동', 'Gangseo-gu', '강서구', 'M231.84,518.94 L228.03,530.12 L227.95,533.5 L233.86,543.73 L235.87,544.98 L224.38,564.37 L220.86,568.5 L216.68,570.88 L207.26,558.55 L205.7,555.18 L205.21,552.45 L204.98,547.94 L205.23,531.3 L210.75,509.85 L232.23,512.68 L231.84,518.94 Z', 'held', '["free-city"]', 'Ujangsan-dong, Gangseo-gu. It lies in the Hwagok section of Gangseo; about 1,200 people live at the two stations Ujangsan and Hwagok. Each station''s foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Gangseo Wind Keeper.', '강서구 우장산동. 강서의 화곡 구간에 든 동으로, 우장산·화곡 두 역에 약 1,200명이 산다. 역마다 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 강서 바람지기다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 2, 1244359.1206966457, 964);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150062000', 257, 'Gonghang-dong', '공항동', 'Gangseo-gu', '강서구', 'M133.44,489.91 L136.81,489.87 L140.61,488.48 L148.73,487.63 L148.69,493.12 L162.34,495.5 L179.33,497.85 L178.54,505.54 L168.52,504.17 L168.88,506.81 L168.31,511.54 L167.55,513.71 L152.07,528.24 L149.92,529.53 L147.23,532.44 L137.4,541.53 L141.84,546.46 L139.59,549.42 L144.94,555.98 L144.59,559.78 L142.19,563.1 L139.09,564.37 L138.95,569.79 L136.2,573.6 L130.53,570.32 L121.83,563.03 L109,564.86 L105.44,567.08 L101.92,569.79 L103.16,572.75 L97.84,574.9 L97.17,577.83 L98.57,578.44 L99.25,583.57 L98.01,584.84 L96.04,584.38 L94.6,586.53 L89.42,587.59 L84.6,590.78 L83.48,587.08 L84.06,582.09 L81.6,576.73 L84.41,575.4 L85.75,570.32 L78,569.19 L77.23,562.22 L64.76,554.53 L56.93,552.91 L48.93,553.39 L44.56,553.28 L36.71,551.71 L34.53,545.79 L30.37,542.69 L22.55,543.96 L20.01,545.37 L15.29,535.72 L10.29,533.53 L8.1,532.12 L8.76,527.48 L4.3,524.3 L4.72,521.41 L0,519.79 L5.5,515.14 L16.16,513.35 L21.21,514.08 L24.17,512.32 L21.07,507.6 L31.53,496.88 L38.05,503.02 L35.51,489.06 L29.88,481.73 L29.31,476.23 L31.71,473.98 L35.45,480.57 L45.73,473.49 L51.44,466.69 L49.78,460.86 L52.11,454.71 L57.52,450.75 L66.09,447.48 L98.93,473.41 L94.84,487.51 L100.34,495.54 L109.28,496.07 L123.3,497.91 L127.48,494.92 L133.02,489.52 L133.44,489.91 Z', 'held', '["free-city"]', 'Gonghang-dong, Gangseo-gu. It lies in the Gimpo Airport and Magok sections of Gangseo; about 5,650 people live at the four stations Airport Market, Gimpo Int''l Airport, Magok and Songjeong. Each station''s foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Gangseo Wind Keeper. Gimpo Airport, a large interchange where five lines pass, is the Gangseo seat. Its old hangars give up sheet metal and long beams. Gangseo-gu lives on the wind-frame fields of the western riverside plain. It makes the most electricity of the Free Cities and has the widest light fields.', '강서구 공항동. 강서의 김포공항·마곡 구간에 든 동으로, 공항시장·김포공항·마곡·송정 네 역에 약 5,650명이 산다. 역마다 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 강서 바람지기다. 김포공항은 다섯 노선이 지나는 큰 환승 단지로 강서의 자리 역이다. 옛 격납고가 금속판과 긴 들보를 내준다. 강서구는 서쪽 강변 벌판의 바람틀 밭으로 산다. 자유도시들 가운데 전기를 가장 많이 만들고 빛밭도 가장 넓다.', 'Winter 2126. The wind keeper is re-measuring every wind field to see whether the watts written into the contract can be met in the long-night season.', '2126년 겨울. 바람지기는 계약서에 적을 와트를 긴 밤 철에 채울 수 있을지 바람밭마다 다시 잰다.', 7, 10927074.979745327, 517);
