INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150064000', 259, 'Banghwa 2-dong', '방화2동', 'Gangseo-gu', '강서구', 'M118.23,346.75 L122.15,350.77 L134.64,364.89 L142.62,368.87 L149.24,375.94 L152.62,377.22 L155.4,383.38 L142.7,407.15 L143.67,407.98 L142.25,409.93 L144.73,411.21 L144.8,412.94 L144.05,417.83 L142.62,423.17 L141.12,419.93 L138.94,418.65 L136.23,421.74 L132.4,419.63 L127.81,419.03 L125.8,421.15 L124.28,423.84 L120.07,424.9 L120.29,427.68 L119.58,429.81 L117.51,433.7 L119.61,433.92 L118.71,439.71 L116.38,442.42 L113.15,451.82 L112.97,453.3 L111.27,455.73 L112.01,458.69 L113.57,458.75 L119.82,458.65 L132.21,456.29 L137.25,465.68 L138.21,468.3 L138,478.19 L137.54,480.87 L136.72,483.1 L133.02,489.52 L127.48,494.92 L123.3,497.91 L109.28,496.07 L100.34,495.54 L94.84,487.51 L98.93,473.41 L66.09,447.48 L73.28,440.43 L74.69,430.56 L78.21,427.6 L81.74,432.68 L83.75,425.99 L87.07,419.87 L89.66,420.58 L90.19,420.45 L93.07,417.37 L93.42,416.79 L94.41,411.75 L97.28,403.81 L98.69,402.27 L101.02,403.02 L103.98,403.48 L104.3,403.11 L104.59,400.41 L104.39,399.49 L99.47,388.29 L94.41,372.11 L93.8,365.28 L95.13,359.87 L96.42,357.14 L104.19,345.15 L106.15,343.74 L108.85,343.18 L112.55,343.75 L114.85,344.54 L118.23,346.75 Z', 'held', '["free-city"]', 'Banghwa 2-dong, Gangseo-gu. It lies in the Gimpo Airport section of Gangseo; about 1,200 people live at the two stations Gaehwa and Gaehwasan. Each station''s foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Gangseo Wind Keeper. The Line 9 Gaehwa depot is frozen. At the western edge, it faces the rim.', '강서구 방화2동. 강서의 김포공항 구간에 든 동으로, 개화·개화산 두 역에 약 1,200명이 산다. 역마다 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 강서 바람지기다. 9호선 개화 기지는 얼어붙었다. 서쪽 끝이라 테두리를 마주한다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 3, 6181922.648143297, 194);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150064100', 260, 'Banghwa 3-dong', '방화3동', 'Gangseo-gu', '강서구', 'M193.9,411.81 L184.5,417.98 L176.16,427.38 L173.15,432.64 L171.12,433.39 L168.34,435.65 L162.7,442.64 L161.42,449.34 L161.95,453.93 L164.9,456.55 L148.95,456.08 L149.11,450.18 L146.9,449.97 L126.32,449.04 L123.3,450.53 L122.69,452.69 L116.4,453.52 L112.97,453.3 L113.15,451.82 L116.38,442.42 L118.71,439.71 L119.61,433.92 L117.51,433.7 L119.58,429.81 L120.29,427.68 L120.07,424.9 L124.28,423.84 L125.8,421.15 L127.81,419.03 L132.4,419.63 L136.23,421.74 L138.94,418.65 L141.12,419.93 L142.62,423.17 L144.05,417.83 L144.8,412.94 L144.73,411.21 L142.25,409.93 L143.67,407.98 L142.7,407.15 L155.4,383.38 L172.32,398.58 L178.86,403.69 L193.9,411.81 Z', 'held', '["free-city"]', 'Banghwa 3-dong, Gangseo-gu. It lies in the Gimpo Airport section of Gangseo; about 600 people live at Banghwa Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Gangseo Wind Keeper. The Line 5 depot at Banghwa still runs and carries Gangseo''s rail work and maintenance locomotives.', '강서구 방화3동. 강서의 김포공항 구간에 든 동으로, 방화역에 약 600명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 강서 바람지기다. 방화의 5호선 차량기지는 살아 있는 기지로 강서의 레일 일과 정비 기관차를 맡는다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 2552797.929997004, 235);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153051000', 261, 'Sindorim-dong', '신도림동', 'Guro-gu', '구로구', 'M372.67,692.42 L368.97,694.82 L362,694.65 L360.94,693.34 L357.91,692.29 L344.84,701.81 L337.52,708.01 L334.82,708.62 L334.12,708.37 L332.7,707.13 L329.58,703.74 L324.65,703.73 L320.68,701.64 L310.58,690.68 L324.99,670.04 L327.96,661.1 L334.42,664.59 L356.96,678.16 L359.95,680.89 L362.99,686.18 L366.48,687.67 L372.67,692.42 Z', 'held', '["free-city"]', 'Sindorim-dong, Guro-gu. It lies in the Sindorim section of Guro; about 2,000 people live at Sindorim Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Guro Works Master. With only three exits, Sindorim is limited by air; the next fan Guro wants to install is this station''s.', '구로구 신도림동. 구로의 신도림 구간에 든 동으로, 신도림역에 약 2,000명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 구로 공장장이다. 신도림은 출구가 셋뿐이라 공기가 한도다. 구로가 다음에 달려는 팬이 이 역의 팬이다.', 'Winter 2126. Guro wants the parts for the Sindorim fan first as its share of the contract.', '2126년 겨울. 구로는 계약 몫으로 신도림 팬을 달 부품을 먼저 받으려 한다.', 3, 1375464.764538088, 1454);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153052000', 262, 'Guro 1-dong', '구로1동', 'Guro-gu', '구로구', 'M330.63,772 L323.3,770.79 L318.24,773.23 L313.65,774 L314.85,770.04 L315.28,762.67 L308.1,761.65 L300.34,750.39 L299.22,748.22 L299.13,745.04 L297.15,738.91 L295.42,738.89 L294.67,731.83 L295.76,734.07 L303.78,732.25 L309.87,728.59 L324.33,722.14 L329.54,721.19 L328.22,725.61 L327.78,731.14 L328.91,748.43 L328.35,752.71 L328.82,762.85 L329.16,766.84 L330.63,772 Z', 'held', '["free-city"]', 'Guro 1-dong, Guro-gu. It lies in the Onsu section of Guro; about 550 people live at Guil Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Guro Works Master.', '구로구 구로1동. 구로의 온수 구간에 든 동으로, 구일역에 약 550명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 구로 공장장이다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 1082490.8651219665, 508);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153053000', 263, 'Guro 2-dong', '구로2동', 'Guro-gu', '구로구', 'M328.63,710.63 L339.18,722.8 L340.48,723.9 L342.51,724.97 L349.72,731.8 L358.76,746.13 L351.74,757.89 L344.67,756.71 L340.86,755.53 L340.52,755.7 L341.56,761.42 L342.58,765.14 L346.08,775.65 L337,769.76 L329.21,767.04 L328.35,752.71 L328.91,748.43 L327.77,729.67 L328.22,725.61 L329.54,721.19 L324.33,722.14 L309.87,728.59 L303.78,732.25 L295.76,734.07 L294.67,731.83 L304.15,701.07 L310.58,690.68 L320.68,701.64 L324.65,703.73 L329.58,703.74 L332.7,707.13 L328.63,710.63 Z', 'held', '["free-city"]', 'Guro 2-dong, Guro-gu. No inhabited station stands in this dong. The ground is buried in snow, and the chief of the Sindorim section, which holds the nearest station, Guro, also holds its scavenging and light-field plots. The city is held by the Guro Works Master.', '구로구 구로2동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 구로역이 든 신도림 구간의 구간장이 이 동의 고물 채집과 빛밭 자리를 함께 쥔다. 이 도시를 쥔 사람은 구로 공장장이다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Guro 2-dong, and only by day. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 구로2동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 0, 1808608.8570230417, 0);
