INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159060500', 311, 'Heukseok-dong', '흑석동', 'Dongjak-gu', '동작구', 'M592.1,707.78 L591.29,708.3 L583.7,710.4 L577.2,716.14 L564.13,732.18 L561.76,730.91 L551.41,727.27 L548.91,725.36 L540.98,708.06 L542.62,698.4 L541.35,695.12 L542.24,695.25 L550.31,687.31 L563.71,676.73 L575.44,685.15 L598.9,696.73 L592.1,707.78 Z', 'held', '["free-city"]', 'Heukseok-dong, Dongjak-gu. It lies in the Noryangjin section of Dongjak; about 550 people live at Heukseok Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Dongjak Ferry Keeper. People fish through holes in the river ice off Heukseok.', '동작구 흑석동. 동작의 노량진 구간에 든 동으로, 흑석역에 약 550명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 동작 나루지기다. 흑석 앞 강 얼음에 구멍을 뚫어 물고기를 잡는다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 1724000.8961817857, 319);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159062000', 312, 'Sadang 1-dong', '사당1동', 'Dongjak-gu', '동작구', 'M621.44,777.95 L619.97,805.49 L620.27,808.33 L613.58,807.37 L606.5,807.5 L593.43,810.16 L588.04,811.73 L587.19,807.2 L599.15,793.56 L600.24,793.63 L602.78,789.74 L603.1,783.32 L613.13,779.39 L620.64,777.77 L621.44,777.95 Z', 'held', '["free-city"]', 'Sadang 1-dong, Dongjak-gu. It lies in the Sadang section of Dongjak; about 2,150 people live at Sadang Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Dongjak Ferry Keeper. Sadang is a land-border station facing Arc''s Bangbae.', '동작구 사당1동. 동작의 사당 구간에 든 동으로, 사당역에 약 2,150명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 동작 나루지기다. 사당은 아크의 방배와 맞닿은 땅 경계의 역이다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 632252.8460421563, 3401);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159063000', 313, 'Sadang 2-dong', '사당2동', 'Dongjak-gu', '동작구', 'M616.31,699.85 L617.14,711.32 L617.88,713.36 L619.14,715 L633.56,726.78 L635.7,728.26 L638.26,728.35 L637.98,729.7 L633.69,728.44 L629.46,725.9 L625.76,732.11 L624.05,736.4 L623.67,740.4 L623.23,756.05 L621.44,777.95 L620.64,777.77 L613.13,779.39 L611.46,770.85 L609.85,770.82 L606.12,769.64 L603.29,766.2 L597.32,757.85 L594.71,753.1 L594.52,749.16 L593.89,747.35 L581.44,744.77 L575.58,746.27 L572.76,747.44 L566.88,742.54 L561.76,730.91 L564.13,732.18 L577.2,716.14 L583.7,710.4 L591.29,708.3 L592.1,707.78 L598.9,696.73 L616.31,699.85 Z', 'held', '["free-city"]', 'Sadang 2-dong, Dongjak-gu. It lies in the Noryangjin and Sadang sections of Dongjak; about 4,300 people live at the two stations Dongjak and Chongshin Univ. (Isu). Each station''s foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Dongjak Ferry Keeper. Dongjak Station is where the three polities meet: Line 4 runs to the Government''s Ichon and Line 9 to Arc''s Gubanpo. Chongshin Univ. (Isu) is a land-border station facing Arc''s Naebang.', '동작구 사당2동. 동작의 노량진·사당 구간에 든 동으로, 동작·총신대입구(이수) 두 역에 약 4,300명이 산다. 역마다 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 동작 나루지기다. 동작역은 4호선으로 정부의 이촌과, 9호선으로 아크의 구반포와 이어지는 세 정체의 교차점이다. 총신대입구(이수)는 아크의 내방과 맞닿은 땅 경계의 역이다.', 'Winter 2126. Envoys of all three polities pass Dongjak Station, so the ferry keeper has reset the crossing toll.', '2126년 겨울. 세 정체의 사절이 모두 동작역을 지나므로 나루지기가 통행 몫을 다시 정했다.', 2, 2743962.1099059954, 1567);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159064000', 314, 'Sadang 3-dong', '사당3동', 'Dongjak-gu', '동작구', 'M603.1,783.32 L599.87,783.28 L586.93,776.77 L578.67,768.49 L576.47,766.18 L567.95,750.76 L564.73,743.98 L566.88,742.54 L572.76,747.44 L575.58,746.27 L581.44,744.77 L593.89,747.35 L594.52,749.16 L594.71,753.1 L597.32,757.85 L603.29,766.2 L606.12,769.64 L609.85,770.82 L611.46,770.85 L613.13,779.39 L603.1,783.32 Z', 'held', '["free-city"]', 'Sadang 3-dong, Dongjak-gu. It lies in the Sadang section of Dongjak; about 550 people live at Namseong Station. The station foreman keeps the workbenches and the exits, and the section chief keeps the section''s tally board. The city is held by the Dongjak Ferry Keeper.', '동작구 사당3동. 동작의 사당 구간에 든 동으로, 남성역에 약 550명이 산다. 역반장이 작업대와 출입구를 맡고, 구간장이 구간의 셈판을 묶는다. 이 도시를 쥔 사람은 동작 나루지기다.', 'Winter 2126. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 0, 893687.957825955, 615);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159065000', 315, 'Sadang 4-dong', '사당4동', 'Dongjak-gu', '동작구', 'M603.1,783.32 L602.78,789.74 L600.24,793.63 L599.15,793.56 L587.19,807.2 L583.22,807.08 L580.42,802.96 L577.58,800.11 L573.3,796.55 L578.28,790.08 L582.26,787.79 L585.79,787.4 L589.9,778.96 L589.24,777.85 L599.87,783.28 L603.1,783.32 Z', 'held', '["free-city"]', 'Sadang 4-dong, Dongjak-gu. No inhabited station stands in this dong. The ground is buried in snow, and the chief of the Sadang section, which holds the nearest station, Namseong, also holds its scavenging and light-field plots. The city is held by the Dongjak Ferry Keeper.', '동작구 사당4동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 남성역이 든 사당 구간의 구간장이 이 동의 고물 채집과 빛밭 자리를 함께 쥔다. 이 도시를 쥔 사람은 동작 나루지기다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Sadang 4-dong, and only by day. Ahead of the third water contract the section chief writes on the tally board the maintenance hand-hours and parts this section will put in. A contract binds only the cities that stamp it.', '2126년 겨울. 사당4동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약을 앞두고 구간장이 이 구간이 낼 정비 손시간과 부품 수를 셈판에 적는다. 계약서는 도장 찍은 도시만 묶는다.', 1, 426936.6744105522, 0);
