INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165054000', 345, 'Jamwon-dong', '잠원동', 'Seocho-gu', '서초구', 'M729.19,666.27 L734.45,683.65 L731.7,684.94 L706.63,693.8 L706.76,690.74 L700.23,678.65 L698.09,675.88 L694.39,678.37 L692.78,674.93 L698.95,667.35 L696.75,665.42 L694.92,663.25 L686.23,650.67 L696.47,635.14 L707.7,623.49 L715.49,631.93 L722.53,641.4 L724.05,644.28 L725.95,649.94 L728.03,658.17 L729.3,665 L729.19,666.27 Z', 'held', '["arc"]', 'Jamwon-dong, Seocho-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 1,800 people live at the two stations Sinsa and Jamwon; the shelter head of Jamwon-dong keeps the baptism roll and each station''s bench keeper keeps its maintenance bench. The Seocho Near House holds the district.', '서초구 잠원동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 신사·잠원 두 역에 약 1,800명이 살고, 잠원동 대피소장이 대피소 사람의 세례 명단을, 역마다 정비장이 정비대를 맡는다. 이 구는 서초 곁집이 맡는다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 1, 1836480.8991248608, 980);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165055000', 346, 'Banpobon-dong', '반포본동', 'Seocho-gu', '서초구', 'M651.84,688.46 L649.96,694.63 L650.93,700.27 L649.79,703.97 L652.86,712.99 L655.78,713.14 L656.5,714.56 L657.47,718.1 L647.63,725.15 L639.38,728.15 L635.7,728.26 L619.14,715 L617.88,713.36 L617.14,711.32 L616.79,708.81 L616.31,699.85 L618.04,699.59 L632.21,699.44 L646.5,676.5 L651.84,688.46 Z', 'held', '["arc"]', 'Banpobon-dong, Seocho-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 350 people live at Gubanpo Station; the shelter head of Banpobon-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Seocho Near House holds the district. Gubanpo is a land-border station joined to Dongjak by Line 9.', '서초구 반포본동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 구반포역에 약 350명이 살고, 반포본동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 서초 곁집이 맡는다. 구반포는 9호선으로 동작과 맞닿은 땅 경계의 역이다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 1, 1045714.1909045074, 335);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165056000', 347, 'Banpo 1-dong', '반포1동', 'Seocho-gu', '서초구', 'M743.47,707.63 L733.64,711.42 L726.73,713.61 L724.34,721 L712.17,725.08 L708.64,725.98 L706.34,714.5 L699.4,697.54 L701.26,695.66 L731.7,684.94 L734.64,684.15 L743.47,707.63 Z', 'held', '["arc"]', 'Banpo 1-dong, Seocho-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 2,150 people live at the three stations Nonhyeon, Banpo and Sapyeong; the shelter head of Banpo 1-dong keeps the baptism roll and each station''s bench keeper keeps its maintenance bench. The Seocho Near House holds the district.', '서초구 반포1동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 논현·반포·사평 세 역에 약 2,150명이 살고, 반포1동 대피소장이 대피소 사람의 세례 명단을, 역마다 정비장이 정비대를 맡는다. 이 구는 서초 곁집이 맡는다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 3, 1009020.4071944489, 2131);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165057000', 348, 'Banpo 2-dong', '반포2동', 'Seocho-gu', '서초구', 'M675.91,704.57 L681.98,714.62 L682.11,715.94 L681.65,716.58 L655.93,729.21 L652.67,729.96 L650.68,730.02 L637.98,729.7 L638.26,728.35 L644.64,726.38 L647.63,725.15 L657.47,718.1 L656.5,714.56 L655.78,713.14 L652.86,712.99 L650.04,705.17 L649.9,703.08 L650.93,700.27 L649.96,694.63 L651.84,688.46 L646.5,676.5 L661.82,666.8 L675.91,704.57 Z', 'held', '["arc"]', 'Banpo 2-dong, Seocho-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 350 people live at Sinbanpo Station; the shelter head of Banpo 2-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Seocho Near House holds the district.', '서초구 반포2동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 신반포역에 약 350명이 살고, 반포2동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 서초 곁집이 맡는다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 1, 1187495.630485557, 295);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165058000', 349, 'Banpo 3-dong', '반포3동', 'Seocho-gu', '서초구', 'M706.63,693.8 L675.91,704.57 L661.82,666.8 L674.6,658.93 L686.23,650.67 L694.92,663.25 L696.75,665.42 L698.95,667.35 L692.78,674.93 L694.39,678.37 L698.09,675.88 L700.23,678.65 L706.76,690.74 L706.63,693.8 Z', 'held', '["arc"]', 'Banpo 3-dong, Seocho-gu. No inhabited station stands in this dong. The ground is buried in snow, and the shelter head of Jamwon-dong, where the nearest station, Jamwon, belongs, also holds its surface land and exit rights. The Seocho Near House holds the district.', '서초구 반포3동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 잠원역이 속한 잠원동 대피소의 대피소장이 이 동의 지상 땅과 출입구 권리를 함께 쥔다. 이 구는 서초 곁집이 맡는다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Banpo 3-dong, and only by day. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 반포3동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 0, 1308172.5707446507, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165058100', 350, 'Banpo 4-dong', '반포4동', 'Seocho-gu', '서초구', 'M708.83,727.15 L703.36,728.14 L700.79,729.44 L683.39,742.2 L681.37,745.37 L673.76,752.53 L665.13,746.24 L660.02,744.99 L659.66,742.33 L658.46,740.28 L658.87,738.69 L658.3,737.65 L655.24,737.21 L654.76,737.79 L652.86,736.59 L652.85,735.55 L652.34,734.54 L648.01,733.29 L647.06,732.35 L646.46,731.02 L646.47,730.03 L652.67,729.96 L655.93,729.21 L658.33,728.23 L681.65,716.58 L682.11,715.94 L681.98,714.62 L675.91,704.57 L701.26,695.66 L699.4,697.54 L706.34,714.5 L708.83,727.15 Z', 'held', '["arc"]', 'Banpo 4-dong, Seocho-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 2,450 people live at Express Bus Terminal Station; the shelter head of Banpo 4-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Seocho Near House holds the district. The Express Bus Terminal, where three lines meet, is the widest station in Seocho; the head of the Seocho Near House lives here and the exchange floor is held here. Seocho-gu holds the Arc side of the three land borders with the Free Cities and the exchange floor at the Express Bus Terminal. Free City workshop talk is strongest here of all Arc.', '서초구 반포4동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 고속터미널역에 약 2,450명이 살고, 반포4동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 서초 곁집이 맡는다. 고속터미널은 세 노선이 만나는 서초에서 가장 넓은 역으로, 서초 곁집장이 살고 바꿈터가 선다. 서초구는 자유도시들과 맞닿은 땅 경계 세 곳의 아크 쪽 역과 고속터미널의 바꿈터를 쥔다. 아크에서 자유도시 작업장 말투가 가장 짙다.', 'Winter 2126. The Seocho Near House wants traffic across the Sadang land border put off until after the contract.', '2126년 겨울. 서초 곁집은 사당 쪽 땅 경계의 통행을 계약 뒤로 미루자고 한다.', 1, 1457423.3782692337, 1681);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165059000', 351, 'Bangbaebon-dong', '방배본동', 'Seocho-gu', '서초구', 'M646.47,730.03 L646.46,731.02 L647.06,732.35 L648.01,733.29 L652.34,734.54 L652.85,735.55 L652.86,736.59 L654.76,737.79 L655.24,737.21 L658.3,737.65 L658.87,738.69 L658.46,740.28 L659.66,742.33 L660.02,744.99 L650.91,746.61 L631.4,756.13 L623.23,756.05 L623.67,740.4 L624.05,736.4 L625.76,732.11 L629.46,725.9 L633.69,728.44 L637.98,729.7 L646.47,730.03 Z', 'held', '["arc"]', 'Bangbaebon-dong, Seocho-gu. No inhabited station stands in this dong. The ground is buried in snow, and the shelter head of Banpobon-dong, where the nearest station, Gubanpo, belongs, also holds its surface land and exit rights. The Seocho Near House holds the district.', '서초구 방배본동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 구반포역이 속한 반포본동 대피소의 대피소장이 이 동의 지상 땅과 출입구 권리를 함께 쥔다. 이 구는 서초 곁집이 맡는다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Bangbaebon-dong, and only by day. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 방배본동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 0, 659153.9888457155, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165060000', 352, 'Bangbae 1-dong', '방배1동', 'Seocho-gu', '서초구', 'M678.98,787.29 L662.09,791.77 L654.52,794.78 L643.15,772.18 L670.29,761.96 L675.24,759.82 L676.29,770.5 L673.67,775.2 L674.54,776.96 L675.23,779.48 L675.21,782.38 L678.23,785.49 L678.98,787.29 Z', 'held', '["arc"]', 'Bangbae 1-dong, Seocho-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 350 people live at Bangbae Station; the shelter head of Bangbae 1-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Seocho Near House holds the district. Bangbae is a land-border station facing Sadang in the Free Cities.', '서초구 방배1동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 방배역에 약 350명이 살고, 방배1동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 서초 곁집이 맡는다. 방배는 자유도시들의 사당과 맞닿은 땅 경계의 역이다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 2, 697545.2251914879, 502);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165061000', 353, 'Bangbae 2-dong', '방배2동', 'Seocho-gu', '서초구', 'M654.52,794.78 L644.06,799.13 L636.35,803.89 L634.27,805.67 L632.72,809.69 L631.58,814.7 L632.32,821.33 L634.75,827.06 L641.25,828.97 L652.13,833.12 L657.49,835.69 L661.83,843.28 L662.32,850.17 L664.48,853.3 L663.34,859.6 L639.7,874.05 L636.91,869.48 L636.44,865.85 L638.71,853.39 L638.54,847.45 L636.92,842.35 L634.85,839.06 L628.19,832.2 L624.52,825.61 L622.54,821.28 L620.64,814.33 L619.97,805.49 L621.49,775.86 L643.15,772.18 L654.52,794.78 Z', 'held', '["arc"]', 'Bangbae 2-dong, Seocho-gu. No inhabited station stands in this dong. The ground is buried in snow, and the shelter head of Bangbae 1-dong, where the nearest station, Bangbae, belongs, also holds its surface land and exit rights. The Seocho Near House holds the district.', '서초구 방배2동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 방배역이 속한 방배1동 대피소의 대피소장이 이 동의 지상 땅과 출입구 권리를 함께 쥔다. 이 구는 서초 곁집이 맡는다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Bangbae 2-dong, and only by day. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 방배2동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 1, 1933043.6208306085, 0);
