INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171068000', 404, 'Jamsil 3-dong', '잠실3동', 'Songpa-gu', '송파구', 'M968.58,695.97 L963.37,699 L959.63,700.79 L955.57,701.64 L953.31,701.57 L927.56,696.35 L924.21,694.5 L922.54,692.93 L921.1,691.02 L919.72,688.08 L918.69,683.59 L921.89,682.56 L927.86,683.36 L938.7,681.93 L927.31,641.27 L927.36,633 L932.87,631.19 L943.59,649.58 L963.71,682.8 L971.56,693.46 L968.58,695.97 Z', 'held', '["arc"]', 'Jamsil 3-dong, Songpa-gu. No inhabited station stands in this dong. The ground is buried in snow, and the shelter head of Jamsil 6-dong, where the nearest station, Jamsil, belongs, also holds its surface land and exit rights. The Songpa Near House holds the district.', '송파구 잠실3동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 잠실역이 속한 잠실6동 대피소의 대피소장이 이 동의 지상 땅과 출입구 권리를 함께 쥔다. 이 구는 송파 곁집이 맡는다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Jamsil 3-dong, and only by day. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 잠실3동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 0, 1513265.3513109174, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171069000', 405, 'Jamsil 4-dong', '잠실4동', 'Songpa-gu', '송파구', 'M996.72,661.27 L979.18,669.14 L968.86,645.72 L954.9,625.68 L957.32,624.27 L972.69,637.77 L977.9,638.94 L1007.27,638.84 L996.72,661.27 Z', 'held', '["arc"]', 'Jamsil 4-dong, Songpa-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 450 people live at Jamsillaru Station; the shelter head of Jamsil 4-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Songpa Near House holds the district. Jamsillaru is the south end of the Line 2 bridge from Gangbyeon.', '송파구 잠실4동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 잠실나루역에 약 450명이 살고, 잠실4동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 송파 곁집이 맡는다. 잠실나루는 강변에서 건너오는 2호선 다리의 남쪽 끝이다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 1, 839566.1465267467, 536);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171071000', 406, 'Jamsil 6-dong', '잠실6동', 'Songpa-gu', '송파구', 'M983.26,681.9 L971.56,693.46 L963.71,682.8 L943.59,649.58 L932.87,631.19 L938.08,628.39 L954.9,625.68 L968.86,645.72 L979.18,669.14 L983.26,681.9 Z', 'held', '["arc"]', 'Jamsil 6-dong, Songpa-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 3,100 people live at Jamsil Station; the shelter head of Jamsil 6-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Songpa Near House holds the district. Jamsil is the Songpa Near House seat, and the Hierophant''s household uses a stretch of its platform and its own maintenance bench. Power from the Jamsil weir wheels reaches it first, and heat is its limit. Songpa-gu holds the south end of the Jamsil weir water wheels and the exchange floors at Garak Market and Jamsil. Holding the power, it is the strongest of the four Near Houses.', '송파구 잠실6동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 잠실역에 약 3,100명이 살고, 잠실6동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 송파 곁집이 맡는다. 잠실은 송파 곁집의 본역이고, 교주의 집이 이 역의 승강장 칸과 정비대를 쓴다. 잠실수중보 수차의 전기가 가장 가까이 닿고, 이 역은 열이 한도다. 송파구는 잠실수중보 수차의 남쪽 끝, 가락시장과 잠실의 바꿈터를 쥔다. 전기를 쥔 송파 곁집은 네 곁집 가운데 가장 힘이 세다.', 'Winter 2126. What Arc brings to the third water contract is the power of the Jamsil weir. The Seat of the Four Near Houses meets in the Hierophant''s household.', '2126년 겨울. 아크가 세 번째 급수계약에 내놓을 것은 잠실수중보의 전력이다. 네 곁집 자리가 교주의 집에서 열린다.', 1, 1397406.1707420482, 2218);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171072000', 407, 'Jamsil 7-dong', '잠실7동', 'Songpa-gu', '송파구', 'M883.02,716.9 L877.39,711.88 L873.39,706.36 L872.32,701.3 L870.59,688.5 L884.46,684.35 L897.92,681.9 L901.13,700.42 L883.02,716.9 Z', 'held', '["arc"]', 'Jamsil 7-dong, Songpa-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 1,750 people live at Sports Complex Station; the shelter head of Jamsil 7-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Songpa Near House holds the district.', '송파구 잠실7동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 종합운동장역에 약 1,750명이 살고, 잠실7동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 송파 곁집이 맡는다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 2, 680053.6344608059, 2573);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174051500', 408, 'Gangil-dong', '강일동', 'Gangdong-gu', '강동구', 'M1178.01,518.75 L1170.3,519.83 L1165.57,519.35 L1162.79,501.07 L1171.01,496.39 L1153.79,470.4 L1154.09,470.1 L1148.21,459.55 L1139.43,450.51 L1151.91,441.56 L1157.48,441.49 L1167.09,439.82 L1172.92,439.26 L1175.95,437.57 L1181.48,435.22 L1183.57,434.78 L1181.56,439.74 L1177.36,443.6 L1176.92,447.53 L1178.2,456.32 L1179.11,458.89 L1183.9,468.5 L1187.57,476.87 L1188.52,482.58 L1188.93,489.77 L1189.37,491.62 L1193.22,501.02 L1195.24,505.03 L1195.65,506.43 L1195.67,511.93 L1195.36,513.93 L1178.01,518.75 Z', 'held', '["arc"]', 'Gangil-dong, Gangdong-gu. No inhabited station stands in this dong. The ground is buried in snow, and the shelter head of Sangilje 2-dong, where the nearest station, Gangil, belongs, also holds its surface land and exit rights. The Gangdong Near House holds the district.', '강동구 강일동. 사람이 사는 역이 없는 동이다. 지상은 눈에 묻혔고, 가장 가까운 강일역이 속한 상일제2동 대피소의 대피소장이 이 동의 지상 땅과 출입구 권리를 함께 쥔다. 이 구는 강동 곁집이 맡는다.', 'Winter 2126. Only light-field hands and scavenging crews go up onto the surface of Gangil-dong, and only by day. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 강일동의 지상에는 낮에만 빛밭 일손과 고물 채집조가 오른다. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 0, 2186049.5868088487, 0);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174052500', 409, 'Sangilje 1-dong', '상일제1동', 'Gangdong-gu', '강동구', 'M1172.55,561.85 L1144.28,564.13 L1141.65,563.56 L1139.71,560.36 L1131.61,561.67 L1129.67,561.62 L1120.88,559.15 L1122.83,526.21 L1147.56,521.87 L1165.57,519.35 L1169.95,547.71 L1171.61,556.85 L1172.99,562.26 L1172.55,561.85 Z', 'held', '["arc"]', 'Sangilje 1-dong, Gangdong-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 700 people live at Sangil-dong Station; the shelter head of Sangilje 1-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Gangdong Near House holds the district. From Sangil-dong at the eastern edge the rim beyond the city line is watched.', '강동구 상일제1동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 상일동역에 약 700명이 살고, 상일제1동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 강동 곁집이 맡는다. 동쪽 끝 상일동에서 서울 경계 너머 테두리를 지켜본다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 1, 1779823.2752693824, 393);
