INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174058000', 416, 'Amsa 2-dong', '암사2동', 'Gangdong-gu', '강동구', 'M1039.92,545 L1037.23,552.82 L1026.26,549.6 L1026.98,547.1 L996.29,546.84 L1000.49,533.1 L1000.59,514.14 L999.43,508.18 L1005.15,509.65 L1008.59,509.05 L1016.29,499.59 L1023.16,494.8 L1024.69,493.87 L1050.79,482.46 L1057.82,478.92 L1056.67,491.53 L1053.45,503.82 L1049.9,510.17 L1048.47,514.21 L1044.37,528.12 L1039.92,545 Z', 'held', '["arc"]', 'Amsa 2-dong, Gangdong-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 700 people live at Amsa Station; the shelter head of Amsa 2-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Gangdong Near House holds the district. The Amsa intake draws water from under the ice; Gangdong catches most of its fish along this bank.', '강동구 암사2동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 암사역에 약 700명이 살고, 암사2동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 강동 곁집이 맡는다. 암사 취수구가 얼음 밑 강물을 끌어온다. 강동은 이 강가에서 물고기를 가장 많이 잡는다.', 'Winter 2126. The water of the Amsa intake is on the scales of this contract too.', '2126년 겨울. 암사 취수구의 물도 이번 계약의 저울에 오른다.', 1, 2440732.3317079623, 287);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174059000', 417, 'Amsa 3-dong', '암사3동', 'Gangdong-gu', '강동구', 'M1088.14,528.26 L1044.37,528.12 L1049.72,510.62 L1053.45,503.82 L1056.67,491.53 L1057.82,478.92 L1091.01,479.69 L1090.46,489.73 L1096.2,504.43 L1092.43,507.88 L1087.05,514.3 L1088.54,522.92 L1088.14,528.26 Z', 'held', '["arc"]', 'Amsa 3-dong, Gangdong-gu. Before Arc was bound together this was a shelter that kept its doors shut. About 700 people live at Amsa History Park Station; the shelter head of Amsa 3-dong keeps the baptism roll and the bench keeper keeps the station''s maintenance bench. The Gangdong Near House holds the district.', '강동구 암사3동. 아크로 묶이기 전에는 따로 문을 닫고 살던 대피소다. 암사역사공원역에 약 700명이 살고, 암사3동 대피소장이 대피소 사람의 세례 명단을, 정비장이 정비대를 맡는다. 이 구는 강동 곁집이 맡는다.', 'Winter 2126. Arc sits at a water contract for the first time. The bench keepers pass on the Hierophant''s word not to cut the long-night charging share.', '2126년 겨울. 세 번째 급수계약에 아크가 처음으로 앉는다. 정비장들은 긴 밤 철의 충전 몫을 줄이지 말라는 교주의 말을 옮긴다.', 1, 1796162.1912960545, 390);
